#include<bits/stdc++.h>

using namespace std;
using ll=long long;

const ll mod=998244353;

vector<vector<ll>> mmul(vector<vector<ll>> &l,vector<vector<ll>> &r){
  ll n=l.size();
  vector<vector<ll>> res(n,vector<ll>(n,0));
  for(ll i=0;i<n;i++){
    for(ll j=0;j<n;j++){
      for(ll k=0;k<n;k++){
        res[i][k]+=l[i][j]*r[j][k];
        res[i][k]%=mod;
      }
    }
  }
  return res;
}

bool issuffix(string &a,string &b){
  ll al=a.size(),bl=b.size();
  if(al<bl){return false;}
  for(ll i=0;i<bl;i++){
    if(a[al-1-i]!=b[bl-1-i]){return false;}
  }
  return true;
}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll n,k;
  cin >> n >> k;
  vector<string> s(k);
  map<string,ll> mp;
  mp[""]=0;
  for(auto &nx : s){
    cin >> nx;
    string pref;
    for(auto &ny : nx){
      pref.push_back(ny);
      mp[pref]=0;
    }
  }

  ll vn=0;
  vector<string> vs;
  for(auto &nx : mp){
    vs.push_back(nx.first);
    nx.second=vn; vn++;
  }

  vector<ll> ban(vn,0);
  vector<vector<ll>> mat(vn,vector<ll>(vn,0));
  for(ll i=0;i<vn;i++){
    for(ll j=0;j<k;j++){
      auto pos=vs[i].find(s[j]);
      if(pos!=string::npos){
        ban[i]=1; break;
      }
    }
  }
  for(ll i=0;i<vn;i++){
    if(ban[i]){continue;}
    for(char c='a';c<='z';c++){
      string ss=vs[i];
      ss.push_back(c);
      ll tg=0;
      for(ll j=0;j<vn;j++){
        if(issuffix(ss,vs[j])){
          if(vs[tg].size()<vs[j].size()){tg=j;}
        }
      }
      if(ban[tg]==0){
        mat[i][tg]++;
      }
    }
  }
  vector<ll> vec(vn,0);
  vec[0]=1;
  while(n>0){
    if(n&1ll){
      vector<ll> nvec(vn,0);
      for(ll i=0;i<vn;i++){
        for(ll j=0;j<vn;j++){
          nvec[j]+=vec[i]*mat[i][j];
          nvec[j]%=mod;
        }
      }
      vec=nvec;
    }
    mat=mmul(mat,mat);
    n>>=1;
  }
  ll res=0;
  for(auto &nx : vec){res+=nx; res%=mod;}
  cout << res << "\n";
  return 0;
}
